import cpmpy as cp
import numpy as np
import json

# Data
n_weeks = 4
n_groups = 3
group_size = 3
n_golfers = n_groups * group_size

# Model definition
model = cp.Model()

# Decision Variables
# assign[w][g][p]: golfer assigned to position p in group g in week w
assign = cp.intvar(0, n_golfers - 1, shape=(n_weeks, n_groups, group_size), name="assign")

# Constraints

# 1. Each golfer plays exactly once per week
for w in range(n_weeks):
    model += [cp.AllDifferent(assign[w].reshape(-1))]

# 2. No repeated pairs: No two golfers play together in the same group more than once
# For each pair of golfers, count the number of weeks they are together in a group, must be <= 1
for g1 in range(n_golfers):
    for g2 in range(g1 + 1, n_golfers):
        together = []
        for w in range(n_weeks):
            for g in range(n_groups):
                # Are both g1 and g2 in group g in week w?
                in_group = cp.all([
                    cp.any(assign[w, g] == g1),
                    cp.any(assign[w, g] == g2)
                ])
                together.append(in_group)
        model += (cp.sum(together) <= 1)

# 3. No duplicate golfers in a group
for w in range(n_weeks):
    for g in range(n_groups):
        model += [cp.AllDifferent(assign[w, g])]

# 4. Symmetry breaking: order golfers in each group
for w in range(n_weeks):
    for g in range(n_groups):
        for p in range(group_size - 1):
            model += (assign[w, g, p] < assign[w, g, p + 1])

# 5. Symmetry breaking: order groups in each week by their first golfer
for w in range(n_weeks):
    for g in range(n_groups - 1):
        model += (assign[w, g, 0] < assign[w, g + 1, 0])

# Solve and print
if model.solve():
    solution = {'assign': assign.value().tolist()}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
