import cpmpy as cp
import numpy as np
import json

# Data
n_boats = 5  # Number of boats
n_periods = 4  # Number of periods
capacity = [6, 8, 12, 12, 12]  # Capacities of the boats
crew_size = [2, 2, 2, 2, 4]  # Crew sizes of the boats

# Model definition
model = cp.Model()

# Decision Variables

# is_host[b]: 1 if boat b is a host, 0 otherwise
is_host = cp.boolvar(shape=n_boats, name="is_host")

# visits[g, h, t]: 1 if guest boat g visits host h at period t
# Only meaningful for g != h
visits = cp.boolvar(shape=(n_boats, n_boats, n_periods), name="visits")

# Constraints

# 1. A boat can only be visited as a host if it is a host
for h in range(n_boats):
    for g in range(n_boats):
        if g != h:
            for t in range(n_periods):
                model += visits[g, h, t] <= is_host[h]
        else:
            for t in range(n_periods):
                model += visits[g, h, t] == 0  # Can't visit itself

# 2. Each guest boat must visit exactly one host in each period (if not a host itself)
for g in range(n_boats):
    for t in range(n_periods):
        # If g is a host, it stays on its own boat, doesn't visit others
        # If g is not a host, it must visit exactly one host (not itself)
        model += cp.sum([visits[g, h, t] for h in range(n_boats) if h != g]) == (1 - is_host[g])

# 3. Host boats do not visit anyone (they stay on their own boat)
for h in range(n_boats):
    for t in range(n_periods):
        model += cp.sum([visits[h, other, t] for other in range(n_boats)]) == 0

# 4. Capacity constraints: For each host h at each period t, the total number of people on board <= capacity[h]
for h in range(n_boats):
    for t in range(n_periods):
        # Host's own crew is always on board if is_host[h]
        # Add all guest crews visiting h at t
        total_people = crew_size[h] * is_host[h] + cp.sum([
            crew_size[g] * visits[g, h, t] for g in range(n_boats) if g != h
        ])
        model += total_people <= capacity[h]

# 5. No guest boat visits the same host more than once
for g in range(n_boats):
    for h in range(n_boats):
        if g != h:
            model += cp.sum([visits[g, h, t] for t in range(n_periods)]) <= 1

# 6. No two guest crews meet more than once
# For each pair of guest boats (g1, g2), count the number of periods they are on the same host
for g1 in range(n_boats):
    for g2 in range(g1+1, n_boats):
        # Only if both are not hosts
        meet_exprs = []
        for h in range(n_boats):
            if h != g1 and h != g2:
                for t in range(n_periods):
                    # Both g1 and g2 visit h at t
                    meet_exprs.append(visits[g1, h, t] * visits[g2, h, t])
        if meet_exprs:
            model += cp.sum(meet_exprs) <= 1

# 7. A host's own crew stays on their own boat at all times (implicit in the model)

# Objective: Minimize the number of host boats
model.minimize(cp.sum(is_host))

# Solve and print
if model.solve():
    solution = {
        "visits": visits.value().astype(int).tolist(),
        "is_host": is_host.value().astype(int).tolist()
    }
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
